use super::*;
use crate::{AppState, PublicIngressConfig, PublicIngressRuntime, ServerConfig};
use actix_web::{http::StatusCode, test::TestRequest};
use rudder_auth_core::SigningKey;
use std::sync::Arc;

const SECRET: &str = "native-browser-auth-test-secret-32-bytes-minimum";
// Generated by installed better-call 1.3.7 signCookieValue, not this verifier.
const VECTOR: &str = "fixture.token%2B%2F.Rq73JnzqaNs0ZxsfCcMcrVTw2nLuR9D40VJs9M%2FX1AQ%3D";

#[test]
fn verifies_issuer_vector_and_rejects_ambiguous_or_corrupt_credentials() {
    assert_eq!(
        verify_cookie(VECTOR, SECRET.as_bytes()).as_deref(),
        Some("fixture.token+/")
    );
    for bad in ["%", "%0g", "token.signature", "", "token."] {
        assert!(verify_cookie(bad, SECRET.as_bytes()).is_none());
    }
    assert!(verify_cookie(VECTOR, b"different-key").is_none());
    let config =
        BrowserAuthConfig::required(SECRET.as_bytes(), false, SessionPolicy::LocalAccount).unwrap();
    let cookie = format!("better-auth.session_token={VECTOR}");
    let request = TestRequest::default()
        .insert_header((header::COOKIE, cookie.as_str()))
        .to_http_request();
    assert!(matches!(
        credential(&config, &request),
        Ok(Credential::Session { .. })
    ));
    let duplicate = TestRequest::default()
        .insert_header((header::COOKIE, format!("{cookie}; {cookie}")))
        .to_http_request();
    assert!(credential(&config, &duplicate).is_err());
    let wrong_mode =
        BrowserAuthConfig::required(SECRET.as_bytes(), true, SessionPolicy::LocalAccount).unwrap();
    assert!(credential(&wrong_mode, &request).is_err());
    let bearer = TestRequest::default()
        .insert_header((header::COOKIE, cookie.as_str()))
        .insert_header((header::AUTHORIZATION, "Bearer invalid"))
        .to_http_request();
    assert!(credential(&config, &bearer).is_err());
    assert!(
        BrowserAuthConfig::required(b"rudder-dev-secret", false, SessionPolicy::LocalAccount)
            .is_err()
    );
}

#[test]
fn implicit_identity_requires_explicit_optional_private_loopback_configuration() {
    let listen = "127.0.0.1:0".parse().unwrap();
    assert!(
        BrowserAuthConfig::local_implicit(listen, "local_trusted", "private", "required").is_err()
    );
    assert!(
        BrowserAuthConfig::local_implicit(listen, "authenticated", "private", "optional").is_err()
    );
    assert!(
        BrowserAuthConfig::local_implicit(listen, "local_trusted", "public", "optional").is_err()
    );
    assert!(
        BrowserAuthConfig::local_implicit(
            "0.0.0.0:0".parse().unwrap(),
            "local_trusted",
            "private",
            "optional"
        )
        .is_err()
    );
    let config =
        BrowserAuthConfig::local_implicit(listen, "local_trusted", "private", "optional").unwrap();
    assert!(
        PublicIngressConfig::new("0.0.0.0:0".parse().unwrap(), "http://127.0.0.1:1", SECRET)
            .unwrap()
            .with_browser_auth(config)
            .is_err()
    );
}

#[test]
fn environment_cannot_downgrade_account_auth_or_select_incomplete_cookie_policy() {
    let parse = |values: &[(&str, &str)]| {
        BrowserAuthConfig::from_lookup(|key| {
            Ok(values
                .iter()
                .find(|(k, _)| *k == key)
                .map(|(_, v)| v.to_string()))
        })
    };
    assert!(parse(&[]).unwrap().is_none());
    assert!(parse(&[("RUDDER_NATIVE_BROWSER_AUTH_SECRET", SECRET)]).is_err());
    assert!(
        parse(&[
            ("RUDDER_NATIVE_BROWSER_AUTH_MODE", "required"),
            ("RUDDER_NATIVE_BROWSER_AUTH_SECRET", SECRET)
        ])
        .is_err()
    );
    assert!(
        parse(&[
            ("RUDDER_NATIVE_BROWSER_AUTH_MODE", "local_implicit"),
            ("RUDDER_DEPLOYMENT_MODE", "local_trusted"),
            ("RUDDER_DEPLOYMENT_EXPOSURE", "private"),
            ("RUDDER_NATIVE_AUTH_REQUIREMENT", "optional")
        ])
        .is_err()
    );
    let exact_secret = format!(" {SECRET} ");
    let config = parse(&[
        ("RUDDER_NATIVE_BROWSER_AUTH_MODE", "required"),
        ("RUDDER_NATIVE_BROWSER_AUTH_SECRET", &exact_secret),
        ("RUDDER_NATIVE_BROWSER_AUTH_SECURE_COOKIE", "true"),
        ("RUDDER_NATIVE_BROWSER_AUTH_SESSION_POLICY", "local_account"),
    ])
    .unwrap()
    .unwrap();
    match config.mode {
        Mode::Required {
            secret,
            secure_cookie,
            ..
        } => {
            assert_eq!(secret, exact_secret.as_bytes());
            assert!(secure_cookie);
        }
        _ => panic!("required session mode expected"),
    }
}

#[test]
fn issuer_descriptor_rejects_policy_drift_and_competing_overrides_without_secret_errors() {
    let descriptor = serde_json::json!({
        "issuer": "better_auth", "secret": SECRET, "secureCookie": true,
        "sessionCookieName": "__Secure-better-auth.session_token",
        "dontRememberCookieName": "__Secure-better-auth.dont_remember",
        "expiresIn": 604800, "updateAge": 86400, "disableSessionRefresh": false,
    });
    assert!(issuer::parse(&descriptor.to_string()).is_ok());
    for (field, value) in [
        ("expiresIn", serde_json::json!(3600)),
        ("updateAge", serde_json::json!(0)),
        ("disableSessionRefresh", serde_json::json!(true)),
        ("secureCookie", serde_json::json!(false)),
        ("sessionCookieName", serde_json::json!("custom.session")),
        (
            "dontRememberCookieName",
            serde_json::json!("custom.remember"),
        ),
        ("issuer", serde_json::json!("local_implicit")),
        ("unknownField", serde_json::json!(SECRET)),
    ] {
        let mut changed = descriptor.clone();
        changed[field] = value;
        let error = issuer::parse(&changed.to_string())
            .err()
            .expect("policy drift must fail");
        assert!(!error.to_string().contains(SECRET));
    }
    let raw = descriptor.to_string();
    assert!(
        BrowserAuthConfig::from_lookup(|key| Ok(match key {
            "RUDDER_NATIVE_BROWSER_AUTH_ISSUER" => Some(raw.clone()),
            "RUDDER_NATIVE_BROWSER_AUTH_MODE" => Some("required".into()),
            _ => None,
        }))
        .is_err()
    );
    let local = serde_json::json!({"issuer":"local_account", "secret":format!(" {SECRET} "), "secureCookie":false});
    match issuer::parse(&local.to_string()).unwrap().mode {
        Mode::Required {
            secret,
            secure_cookie,
            session_policy,
        } => {
            assert_eq!(secret, format!(" {SECRET} ").as_bytes());
            assert!(!secure_cookie);
            assert_eq!(session_policy, SessionPolicy::LocalAccount);
        }
        _ => panic!("issuer must require a session"),
    }
}

async fn start(
    database_url: Option<String>,
    config: BrowserAuthConfig,
) -> (
    String,
    actix_web::dev::ServerHandle,
    actix_web::rt::task::JoinHandle<std::io::Result<()>>,
) {
    let foundation = Arc::new(
        AppState::new(ServerConfig {
            database_url,
            actor_envelope_key: Some(SigningKey::new(SECRET.as_bytes()).unwrap()),
            workers: 1,
            ..ServerConfig::default()
        })
        .unwrap(),
    );
    // No Node listener exists: any authorization/query fallback fails this test.
    let config =
        PublicIngressConfig::new("127.0.0.1:0".parse().unwrap(), "http://127.0.0.1:1", SECRET)
            .unwrap()
            .with_browser_auth(config)
            .unwrap();
    let runtime = PublicIngressRuntime::bind(config, foundation).unwrap();
    let url = format!("http://{}", runtime.bound_addr());
    let control = runtime.control();
    (url, control, actix_web::rt::spawn(runtime.run()))
}

#[actix_web::test]
async fn native_session_namespace_never_falls_through_when_storage_is_disabled() {
    let (base, control, task) = start(
        None,
        BrowserAuthConfig::required(SECRET.as_bytes(), false, SessionPolicy::LocalAccount).unwrap(),
    )
    .await;
    let client = awc::Client::default();
    assert_eq!(
        client
            .get(format!("{base}/api/auth/get-session"))
            .send()
            .await
            .unwrap()
            .status(),
        StatusCode::SERVICE_UNAVAILABLE
    );
    for path in [
        "/API/auth/get-session",
        "/api/auth/get-session/",
        "/api/auth/%67et-session",
        "/api/auth/%2567et-session",
        "/api//auth/get-session",
        "/api/auth/get-session/extra",
    ] {
        assert_eq!(
            client
                .get(format!("{base}{path}"))
                .send()
                .await
                .unwrap()
                .status(),
            StatusCode::NOT_FOUND,
            "{path}"
        );
    }
    assert_eq!(
        client
            .post(format!("{base}/api/auth/get-session"))
            .send()
            .await
            .unwrap()
            .status(),
        StatusCode::NOT_FOUND
    );
    for method in [
        actix_web::http::Method::HEAD,
        actix_web::http::Method::OPTIONS,
    ] {
        assert_eq!(
            client
                .request(method, format!("{base}/api/auth/get-session"))
                .send()
                .await
                .unwrap()
                .status(),
            StatusCode::NOT_FOUND
        );
    }
    control.stop(true).await;
    task.await.unwrap().unwrap();
}

#[actix_web::test]
#[ignore = "requires migrated disposable PostgreSQL and cookies from issue_browser_sessions.mts"]
async fn real_issuer_cookies_public_listener_revocation_memberships_and_bearer_precedence() {
    let database_url = std::env::var("RUDDER_NATIVE_AUTH_TEST_DATABASE_URL").unwrap();
    assert!(
        url::Url::parse(&database_url)
            .unwrap()
            .path()
            .contains("test")
    );
    let fixture: serde_json::Value = serde_json::from_slice(
        &std::fs::read(std::env::var("RUDDER_BROWSER_AUTH_FIXTURE").unwrap()).unwrap(),
    )
    .unwrap();
    assert_eq!(fixture["secret"], SECRET);
    let pool = sqlx::PgPool::connect(&database_url).await.unwrap();
    let client = awc::Client::default();
    let org: String = sqlx::query_scalar("INSERT INTO organizations (url_key,name,issue_prefix) VALUES ($1,'Native browser auth',$2) RETURNING id::text")
        .bind(format!("auth-{}", uuid::Uuid::new_v4())).bind(format!("N{}", &uuid::Uuid::new_v4().simple().to_string()[..8])).fetch_one(&pool).await.unwrap();
    for issued in fixture["fixtures"].as_array().unwrap() {
        let user = issued["userId"].as_str().unwrap();
        let cookie = issued["cookie"].as_str().unwrap();
        let config = BrowserAuthConfig::required(
            SECRET.as_bytes(),
            issued["secure"].as_bool().unwrap(),
            if issued["issuer"] == "better-auth" {
                SessionPolicy::BetterAuth
            } else {
                SessionPolicy::LocalAccount
            },
        )
        .unwrap();
        let (base, control, task) = start(Some(database_url.clone()), config.clone()).await;
        let endpoint = format!("{base}/api/auth/get-session");
        let mut response = client
            .get(&endpoint)
            .insert_header((header::COOKIE, cookie))
            .send()
            .await
            .unwrap();
        assert_eq!(
            response.status(),
            StatusCode::OK,
            "issuer {}",
            issued["issuer"]
        );
        assert_eq!(
            response.headers().get(header::CACHE_CONTROL).unwrap(),
            "no-store"
        );
        let dto: serde_json::Value = response.json().await.unwrap();
        let refreshed: bool = sqlx::query_scalar(
            "SELECT expires_at>now()+interval '6 days' FROM session WHERE user_id=$1",
        )
        .bind(user)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(
            refreshed,
            issued["referenceRefresh"].as_bool().unwrap(),
            "issuer expiry refresh must match its real resolver"
        );

        assert_eq!(
            dto,
            serde_json::json!({"session":{"id":format!("rudder:session:{user}"),"userId":user},"user":{"id":user,"email":null,"name":null}})
        );
        assert_eq!(
            client
                .get(&endpoint)
                .insert_header((header::COOKIE, cookie))
                .insert_header((header::AUTHORIZATION, "Bearer pcp_invalid"))
                .send()
                .await
                .unwrap()
                .status(),
            StatusCode::UNAUTHORIZED
        );
        assert_eq!(
            client
                .get(&endpoint)
                .insert_header((
                    header::COOKIE,
                    cookie.replacen("session_token=", "session_token=tampered", 1),
                ))
                .send()
                .await
                .unwrap()
                .status(),
            StatusCode::UNAUTHORIZED
        );
        // The same native resolver revalidates scope, not the UI session ID.
        let request = TestRequest::default()
            .insert_header((header::COOKIE, cookie))
            .to_http_request();
        let mut connection = pool.acquire().await.unwrap();
        assert!(matches!(
            authenticate(&config, &request, &mut connection, Some(&org)).await,
            Err(BrowserAuthError::Forbidden)
        ));
        sqlx::query("INSERT INTO organization_memberships(org_id,principal_type,principal_id,status) VALUES($1::uuid,'user',$2,'active')").bind(&org).bind(user).execute(&pool).await.unwrap();
        let actor = authenticate(&config, &request, &mut connection, Some(&org))
            .await
            .unwrap();
        assert_eq!(actor.user_id(), user);
        assert_ne!(actor.session_id(), dto["session"]["id"].as_str().unwrap());
        sqlx::query("UPDATE organization_memberships SET status='inactive' WHERE org_id=$1::uuid AND principal_id=$2").bind(&org).bind(user).execute(&pool).await.unwrap();
        assert!(matches!(
            authenticate(&config, &request, &mut connection, Some(&org)).await,
            Err(BrowserAuthError::Forbidden)
        ));
        sqlx::query("INSERT INTO instance_user_roles(user_id,role) VALUES($1,'instance_admin')")
            .bind(user)
            .execute(&pool)
            .await
            .unwrap();
        assert!(
            authenticate(&config, &request, &mut connection, Some(&org))
                .await
                .is_ok()
        );
        sqlx::query("DELETE FROM instance_user_roles WHERE user_id=$1")
            .bind(user)
            .execute(&pool)
            .await
            .unwrap();
        // No browser cache can preserve a revoked or expired DB session.
        sqlx::query("UPDATE session SET expires_at=now()-interval '1 second' WHERE user_id=$1")
            .bind(user)
            .execute(&pool)
            .await
            .unwrap();
        assert_eq!(
            client
                .get(&endpoint)
                .insert_header((header::COOKIE, cookie))
                .send()
                .await
                .unwrap()
                .status(),
            StatusCode::UNAUTHORIZED
        );
        sqlx::query("UPDATE session SET expires_at=now()+interval '1 hour' WHERE user_id=$1")
            .bind(user)
            .execute(&pool)
            .await
            .unwrap();
        assert_eq!(
            client
                .get(&endpoint)
                .insert_header((header::COOKIE, cookie))
                .send()
                .await
                .unwrap()
                .status(),
            StatusCode::OK
        );
        sqlx::query("DELETE FROM session WHERE user_id=$1")
            .bind(user)
            .execute(&pool)
            .await
            .unwrap();
        assert_eq!(
            client
                .get(&endpoint)
                .insert_header((header::COOKIE, cookie))
                .send()
                .await
                .unwrap()
                .status(),
            StatusCode::UNAUTHORIZED
        );
        let token = format!("pcp_browser_{}", uuid::Uuid::new_v4());
        sqlx::query("INSERT INTO board_api_keys(user_id,name,key_hash) VALUES($1,'test',$2)")
            .bind(user)
            .bind(crate::native_bearer_auth::hash_token(&token))
            .execute(&pool)
            .await
            .unwrap();
        let mut board = client
            .get(&endpoint)
            .insert_header((header::AUTHORIZATION, format!("Bearer {token}")))
            .send()
            .await
            .unwrap();
        assert_eq!(board.status(), StatusCode::OK);
        let body: serde_json::Value = board.json().await.unwrap();
        assert_eq!(body["session"]["id"], format!("rudder:board_key:{user}"));
        sqlx::query("UPDATE board_api_keys SET revoked_at=now() WHERE user_id=$1")
            .bind(user)
            .execute(&pool)
            .await
            .unwrap();
        assert_eq!(
            client
                .get(&endpoint)
                .insert_header((header::AUTHORIZATION, format!("Bearer {token}")))
                .send()
                .await
                .unwrap()
                .status(),
            StatusCode::UNAUTHORIZED
        );
        control.stop(true).await;
        task.await.unwrap().unwrap();
    }
    let implicit = BrowserAuthConfig::local_implicit(
        "127.0.0.1:0".parse().unwrap(),
        "local_trusted",
        "private",
        "optional",
    )
    .unwrap();
    let (base, control, task) = start(Some(database_url), implicit).await;
    let mut response = client
        .get(format!("{base}/api/auth/get-session"))
        .send()
        .await
        .unwrap();
    assert_eq!(response.status(), StatusCode::OK);
    let body: serde_json::Value = response.json().await.unwrap();
    assert_eq!(body["session"]["id"], "rudder:local_implicit:local-board");
    assert_eq!(body["user"]["name"], "Local Board");
    control.stop(true).await;
    task.await.unwrap().unwrap();
    pool.close().await;
}
